local pm=r:GetProjectManager() local p=pm:GetCurrentProject() assert(p:GetName()=="VEL_Weekender_OldMoney_FourColors_20260913") local t=p:GetCurrentTimeline() local changed=0
for _,kind in ipairs({"video","audio"}) do for track=1,t:GetTrackCount(kind) do for _,c in ipairs(t:GetItemListInTrack(kind,track)) do local m=c:GetMediaPoolItem() if m then local dest=mapping[m:GetClipProperty("File Path")] if dest then local a=c:GetStart() local b=c:GetEnd() assert(m:ReplaceClip(dest)) assert(c:GetStart()==a and c:GetEnd()==b) changed=changed+1 end end end end end
assert(changed==4,"Expected four copied media sources") assert(pm:SaveProject()) return {changed=changed,project=p:GetName(),timeline=t:GetName(),ending=t:GetEndFrame()}
